837	/// Move a config file among the positionals into `--config`, so `iiac-perf queue.md` is
838	/// `iiac-perf --config queue.md`, the common line without the flag. `init-config` and
839	/// `update-config` keep theirs, their one positional being a file to write.
840	fn take_config_arg(cli: &mut Cli) -> Result<(), String> {
841	    if cli
842	        .benches
843	        .first()
844	        .is_some_and(|w| w == "init-config" || w == "update-config")
845	    {
846	        return Ok(());
847	    }
848	    let (files, names): (Vec<String>, Vec<String>) =
849	        cli.benches.drain(..).partition(|w| is_config_arg(w));
850	    cli.benches = names;
851	    let mut files = files.into_iter();
852	    let Some(file) = files.next() else {
853	        return Ok(());
854	    };
855	    if let Some(second) = files.next() {
856	        return Err(format!(
857	            "'{file}' and '{second}' both name the run's config: a run has one"
858	        ));
859	    }
