953	/// A host not set up for the run: name what it lacks, and on a terminal offer `setup --apply`,
954	/// then run the same command again once it is set up. Off a terminal, or declined, exit 2 naming
955	/// the command and the opt-outs.
956	fn not_set_up(gaps: &[String]) -> ! {
957	    eprintln!("This host is not set up for this run:");
958	    for g in gaps {
959	        eprintln!("  - {g}");
960	    }
961	    eprintln!("{}", binary_line());
962	    let terminal = unsafe { libc::isatty(0) == 1 && libc::isatty(2) == 1 };
963	    if terminal {
964	        eprint!("Set it up now with `{BIN_NAME} setup --apply`? [y/N] ");
965	        let mut answer = String::new();
966	        // OK: an unreadable answer is no answer, which declines.
967	        std::io::stdin().read_line(&mut answer).unwrap_or_default();
968	        if matches!(answer.trim(), "y" | "Y" | "yes") {
969	            eprintln!();
970	            let code = setup::run_setup(true);
971	            if code != 0 {
972	                std::process::exit(code);
973	            }
974	            eprintln!();
975	            eprintln!("Set up. Running the command again.");
976	            eprintln!();
977	            // The same command from the start, reading the config setup just wrote.
978	            use std::os::unix::process::CommandExt;
979	            let err = match std::env::current_exe() {
980	                Ok(exe) => std::process::Command::new(exe)
981	                    .args(std::env::args_os().skip(1))
982	                    .exec(),
983	                Err(e) => e,
984	            };
985	            eprintln!("error: running the command again: {err}");
986	            std::process::exit(1);
987	        }
988	    }
989	    eprintln!(
990	        "Run `{BIN_NAME} setup` to see what it would do and `{BIN_NAME} setup --apply` to do it, \
991	         or run unpinned with --pin-cpus \"\" --pin-freq=no."
992	    );
993	    std::process::exit(2);
994	}
