1025	/// Wrap a name list into comma-separated lines of at most `width`
1026	/// columns, each line indented two spaces: the no-benches
1027	/// listing's counterpart of clap's two-column help style.
1028	fn wrap_names(names: &[&str], width: usize) -> String {
1029	    let mut out = String::new();
1030	    let mut col = 0;
1031	    for name in names {
1032	        if out.is_empty() {
1033	            out.push_str("  ");
1034	        } else if col + 2 + name.len() <= width {
1035	            out.push_str(", ");
1036	        } else {
1037	            out.push_str(",\n  ");
1038	            col = 0;
1039	        }
1040	        out.push_str(name);
1041	        col += 2 + name.len();
1042	    }
