2258	    // The record target goes to the children absolute.
2259	    let record_spec = child::RecordSpec {
2260	        target: record_target.as_ref().map(record::Target::absolute),
2261	        tags,
2262	        config: record_config,
2263	        series: record::new_series_id(),
2264	        binary: binary.clone(),
2265	    };
2266	    let mut runner = runs::Runner::new(runs::Plan {
2267	        exe: &exe,
2268	        scratch: scratch.path(),
2269	        runs,
2270	        run_sleep_s,
2271	        verbose,
2272	        decimals: decimals as usize,
2273	        trim_runs,
2274	    });
2275	    // Placements outer and benches inner, so each placement's rows run back to back as one run
2276	    // of a single placement would. A bench whose threads would use the CPUs an earlier
2277	    // placement's run used, a 1t bench at every pair sharing a first CPU, is not run again.
2278	    let mut table = runs::PlacementTable::new(&placements, &runners);
2279	    let mut ran: Vec<(&str, Vec<Option<usize>>, usize)> = Vec::new();
2280	    for (col, p) in placements.iter().enumerate() {
2281	        let pcfg = harness::RunCfg {
2282	            pin_cpus: &p.cpus,
2283	            pin_name: p.name.as_deref(),
2284	            ..cfg
2285	        };
2286	        if several_placements {
2287	            println!("Placement {}: {}\n", p.label(), pin::placement(&p.cpus));
2288	        }
2289	        for (row, entry) in runners.iter().enumerate() {
2290	            let used = pin::thread_cpus(&p.cpus, entry.roles.threads(0).len());
2291	            if let Some(&(_, _, earlier)) = ran
2292	                .iter()
2293	                .find(|(name, cpus, at)| *name == entry.name && *cpus == used && *at != col)
2294	            {
2295	                println!(
2296	                    "{}: at {}, not run: its threads use the CPUs they used at {}\n",
2297	                    entry.name,
2298	                    p.label(),
2299	                    placements[earlier].label()
2300	                );
2301	                table.same(row, col, earlier);
2302	                continue;
2303	            }
2304	            ran.push((entry.name, used, col));
2305	            match runner.bench(entry.name, &pcfg, &record_spec) {
2306	                Ok(means) => table.ran(row, col, means),
2307	                Err(e) => {
2308	                    eprintln!("error: {e}");
2309	                    drop(scratch);
2310	                    drop(freq_pin);
2311	                    std::process::exit(1);
2312	                }
2313	            }
2314	        }
2315	    }
2316	    if several_placements {
2317	        table.print(decimals as usize);
2318	    }
