2329	/// The run flags on the line as config keys, for `init-config` to set in the file it writes: a

2330	/// flag's key and its value as the config spells it. A flag that is not a run parameter is an
2331	/// error by name, since a flag this command ignored in silence once wrote a file of defaults.
2332	fn line_values(cli: &Cli) -> Result<toml::Table, String> {
2333	    use toml::Value;
2334	    for (set, flag) in [
2335	        (cli.print_only, "--print-only"),
2336	        (cli.as_config, "--as-config"),
2337	        (cli.apply, "--apply"),
2338	    ] {
2339	        // --backup and --overwrite say what to do with the file, and their commands read them.
2340	        if set {
2341	            return Err(format!("{flag} is not a run parameter, so no key holds it"));
2342	        }
2343	    }
2344	    let count = |n: u64, flag: &str| match i64::try_from(n) {
2345	        Ok(n) => Ok(Value::Integer(n)),
2346	        Err(_) => Err(format!("{flag}: {n} is too large for a config")),
2347	    };
2348	    let text = |s: &str| Value::String(s.to_string());
2349	    let mut t = toml::Table::new();
2350	    if !cli.benches_flag.is_empty() {
2351	        let names = cli.benches_flag.iter().map(|b| text(b)).collect();
2352	        t.insert("benches".to_string(), Value::Array(names));
2353	    }
2354	    // Seconds reach here parsed, so a `-d 250ms` is written `0.25`.
2355	    for (key, value) in [
2356	        ("duration", cli.duration),
2357	        ("total_duration", cli.total_duration),
2358	        ("settle_time", cli.settle_time),
2359	        ("warm_cap", cli.warm_cap),
2360	    ] {
2361	        if let Some(seconds) = value {
2362	            t.insert(key.to_string(), Value::Float(seconds));
2363	        }
2364	    }
2365	    for (key, flag, value) in [
2366	        ("samples", "--samples", cli.samples),
2367	        ("runs", "--runs", cli.runs),
2368	        ("blocks", "--blocks", cli.blocks),
2369	        ("decimals", "--decimals", cli.decimals.map(u64::from)),
2370	    ] {
2371	        if let Some(n) = value {
2372	            t.insert(key.to_string(), count(n, flag)?);
2373	        }
2374	    }
2375	    // A count is written as the integer it always was, and a span as its text.
2376	    if let Some(span) = cli.inner {
2377	        let value = if span.is_fixed() {
2378	            count(span.lo(), "--inner")?
2379	        } else {
2380	            text(&span.to_string())
2381	        };
2382	        t.insert("inner".to_string(), value);
2383	    }
2384	    for (key, value) in [
2385	        ("pin_cpus", cli.pin_cpus.as_deref()),
2386	        ("run_sleep", cli.run_sleep.as_deref()),
2387	        ("trim_runs", cli.trim_runs.as_deref()),
2388	        ("block_sleep", cli.block_sleep.as_deref()),
2389	        ("block_warmup", cli.block_warmup.as_deref()),
2390	        (
2391	            "band_labels",
2392	            cli.band_labels.map(bands::BandLabels::as_str),
2393	        ),
2394	    ] {
2395	        if let Some(s) = value {
2396	            t.insert(key.to_string(), text(s));
2397	        }
2398	    }
2399	    for (key, value) in [
2400	        ("record_dir", &cli.record_dir),
2401	        ("record_file", &cli.record_file),
2402	    ] {
2403	        if let Some(path) = value {
2404	            t.insert(key.to_string(), text(&path.to_string_lossy()));
2405	        }
2406	    }
2407	    // The two `no-` flags are the key's opposite.
2408	    for (key, value) in [
2409	        ("verbose", cli.verbose),
2410	        ("ticks", cli.ticks),
2411	        ("env_probe", cli.no_env_probe.map(|no| !no)),
2412	        ("inhibit", cli.no_inhibit.map(|no| !no)),
2413	    ] {
2414	        if let Some(on) = value {
2415	            t.insert(key.to_string(), Value::Boolean(on));
2416	        }
2417	    }
2418	    // A bare --pin-freq is the word it stands for, and a frequency is a number.
2419	    let pin_freq = match &cli.pin_freq {
2420	        None => None,
2421	        Some(None) => Some(text("pin_mhz")),
2422	        Some(Some(word)) => Some(match word.parse::<i64>() {
2423	            Ok(mhz) => Value::Integer(mhz),
2424	            Err(_) => text(word),
2425	        }),
2426	    };
2427	    if let Some(value) = pin_freq {
2428	        t.insert("pin_freq".to_string(), value);
2429	    }
2430	    if !cli.tag.is_empty() || cli.record_label.is_some() {
2431	        let mut tags = toml::Table::new();
2432	        if let Some(label) = &cli.record_label {
2433	            tags.insert(record::LABEL_TAG.to_string(), text(label));
2434	        }
2435	        for tag in &cli.tag {
2436	            match tag.split_once('=') {
2437	                Some((k, v)) if !k.is_empty() => tags.insert(k.to_string(), text(v)),
2438	                _ => return Err(format!("--tag '{tag}' is not key=value")),
2439	            };
2440	        }
2441	        t.insert("tags".to_string(), Value::Table(tags));
2442	    }
2443	    Ok(t)
2444	}
