2475	/// A span of seconds as the `Config:` list prints it: `0`, one duration, or a range.
2476	fn span_value(span: (f64, f64)) -> String {
2477	    if span.1 <= 0.0 {
2478	        "0".to_string()
2479	    } else if span.0 == span.1 {
2480	        timespec::display(span.0)
2481	    } else {
2482	        let (lo, hi) = (timespec::display(span.0), timespec::display(span.1));
2483	        // One unit for both ends reads as the flag is typed, `1-10 ms`.
2484	        match (lo.split_once(' '), hi.split_once(' ')) {
2485	            (Some((lo_n, lo_u)), Some((hi_n, hi_u))) if lo_u == hi_u => {
2486	                format!("{lo_n}-{hi_n} {hi_u}")
2487	            }
2488	            _ => format!("{lo}-{hi}"),
2489	        }
2490	    }
2491	}
