fn main() {
    // Shell completion: when the shell set COMPLETE, answer with
    // the candidates and exit before anything else runs.
    CompleteEnv::with_factory(cli::Cli::command).complete();
    let cli = cli::Cli::parse();

    // The bench-name listing is a pure print-and-exit path: no
    // logging, no config, no setup.
    if cli.list_benches {
        for name in benches::names() {
            println!("{name}");
        }
        return;
    }

    // A bench child runs its one bench from the parent's spec and exits: no config, no inhibit,
    // no clock pin, and no banner, all of which the parent owns, its `-v` included.
    if let Some(spec) = &cli.child_spec {
        init_logger(cli.verbose == Some(true));
        std::process::exit(child::child_main(spec));
    }

    match cli.command {
        None => print_bench_list(&format!(
            "no command given: '{BIN_NAME} run BENCH...' runs benches, and -h lists the commands."
        )),
        Some(cli::Command::Run(mut run)) => {
            if let Err(e) = run.take_config_arg() {
                eprintln!("error: {e}");
                std::process::exit(2);
            }
            bench_run(BenchLine {
                benches: std::mem::take(&mut run.benches),
                config: run.config.as_deref(),
                measure: &run.measure,
                verbose: cli.verbose,
                suggest: None,
            });
        }
        Some(cli::Command::Legacy(words)) => legacy(cli.verbose, words),
    }
}

/// The bench list, after the banner and a line saying why it printed: a bare `iiac-perf`, and a
/// `run` that names no benches anywhere.
fn print_bench_list(why: &str) {
    println!("{ABOUT}\n");
    println!("{why}\n");
    println!("Benches:");
    println!("{}", wrap_names(&benches::names(), 72));
}

/// Refuse the retired `--record` before any setup, since an exit past the clock pin skips its
/// restore.
fn refuse_retired_record(m: &cli::MeasureArgs) {
    if m.record.is_some() {
        eprintln!(
            "error: --record is gone, since a path's trailing '/' picked its mode: \
             --record-dir DIR writes a file per invocation, --record-file PATH appends every \
             record to one file"
        );
        std::process::exit(2);
    }
}

/// The command words not yet subcommands of their own, parsed by the flat [`cli::Legacy`] as
/// before. A first word that is none of them is a bench, which runs under `run`.
fn legacy(verbose: Option<bool>, words: Vec<String>) {
    let cli = match cli::Legacy::try_parse_from(std::iter::once(BIN_NAME.to_string()).chain(words))
    {
        Ok(cli) => cli,
        Err(e) => e.exit(),
    };
    let verbose = cli.verbose.or(verbose);
    // The external subcommand always carries its word.
    let word = cli.words.first().cloned().unwrap_or_default();
    if word == "all" || !cli::COMMAND_WORDS.iter().any(|(w, _)| *w == word) {
        eprintln!(
            "error: '{word}' is not a command: benches run as '{BIN_NAME} run {}'",
            cli.words.join(" ")
        );
        std::process::exit(2);
    }
    refuse_retired_record(&cli.measure);

@@LEGACY_COMMANDS@@
}

