import re, subprocess, sys
root = '/home/wink/data/prgs/rust/iiac-perf/'
files = subprocess.run(['git','-C',root,'ls-files','*.md'],capture_output=True,text=True).stdout.split()
skip = ('notes/chores/','notes/done.md','agent-data/','AGENTS.md','CLAUDE.md','custom.md','zCLOSED.md','zDOING.md','messages/')
files = [f for f in files if not f.startswith(skip)]
words = {'read-freq':'freq read','pin-freq':'freq pin','restore-freq':'freq restore','suggest-freq':'freq suggest','setup-freq':'setup freq','setup-uninstall':'setup uninstall','init-config':'config init','update-config':'config update','qualify-environment':'qualify'}
wpat = re.compile(r'(?<![-\w/.])(' + '|'.join(map(re.escape, words)) + r')(?![-\w])')
subs = {'run','qualify','analyze','linear-regression','lr','figures','describe-record','freq','setup','config','help'}
top = {'-h','--help','-V','--version','--list-benches'}
bpat = re.compile(r'(^|[\s`($])(iiac-perf(?:-dev)?) (?=(\S+))')
def fix_code(code):
    code = wpat.sub(lambda m: words[m.group(1)], code)
    def b(m):
        tok = m.group(3).strip('`')
        if tok in subs or tok in top or tok[:1].isdigit() or tok.startswith(('<','[','|','#')) or tok in {'-','--'}:
            return m.group(0)
        return f'{m.group(1)}{m.group(2)} run '
    return bpat.sub(b, code)
report = {}
for f in files:
    text = open(root+f).read()
    out, n = [], 0
    infence = False
    for line in text.split('\n'):
        if line.lstrip().startswith('```'):
            infence = not infence; out.append(line); continue
        if infence:
            new = fix_code(line)
        else:
            # inline code spans only, and the old words anywhere in prose
            new = re.sub(r'`[^`]+`', lambda m: fix_code(m.group(0)), line)
            new = wpat.sub(lambda m: words[m.group(1)], new)
        if new != line: n += 1
        out.append(new)
    if n:
        open(root+f,'w').write('\n'.join(out)); report[f] = n
print(report)
